 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0] = min(b[0], y)
                    b[1] = max(b[1], y)
                    b[2] = min(b[2], x)
                    b[3] = max(b[3], x)
            layers = sorted(boxes, key=lambda color: -((boxes[color][1] - boxes[color][0] + 1) * (boxes[color][3] - boxes[color][2] + 1)))
            reversed_colors = list(reversed(layers))
            mapping = dict(zip(layers, reversed_colors))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out


